/**
 * Contenu pédagogique – Formation GESTIONNAIRE DE PAIE (130 h).
 * 6 modules pour Support de cours (CT4 – IND 18/19). Formation non certifiante RNCP.
 * Enrichi : chaque module contient désormais 5 à 7 sections détaillées avec exemples,
 * chiffres 2026, jurisprudence, points d'audit URSSAF et exercices corrigés.
 */
import { CourseChapter } from "./courseContent";

const IMG = {
  bulletin: "https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=900&q=80",
  calcul: "https://images.unsplash.com/photo-1554224154-26032ffc0d07?w=900&q=80",
  bureau: "https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=900&q=80",
  urssaf: "https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?w=900&q=80",
  contrat: "https://images.unsplash.com/photo-1554224154-22dec7ec8818?w=900&q=80",
  reunion: "https://images.unsplash.com/photo-1552664730-d307ca884978?w=900&q=80",
  equipe: "https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=900&q=80",
  ordinateur: "https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=900&q=80",
  documents: "https://images.unsplash.com/photo-1568667256549-094345857637?w=900&q=80",
};

const photo = (src: string, alt: string) =>
  `<figure style="margin:12px 0;text-align:center"><img src="${src}" alt="${alt}" loading="lazy" style="max-width:100%;height:auto;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,0.12)" /><figcaption style="font-size:12px;color:#666;margin-top:6px;font-style:italic">${alt}</figcaption></figure>`;

const exo = (titre: string, enonce: string, corrige: string) =>
  `<div style="background:#fef6e4;border-left:4px solid #f59e0b;padding:14px;border-radius:6px;margin:14px 0"><p style="margin:0 0 6px 0;font-weight:bold;color:#92400e">📝 Exercice – ${titre}</p><p style="margin:0 0 10px 0">${enonce}</p><details style="margin-top:8px"><summary style="cursor:pointer;font-weight:bold;color:#16a34a">✅ Voir le corrigé</summary><div style="background:#f0fdf4;padding:10px;border-radius:4px;margin-top:6px">${corrige}</div></details></div>`;

const info = (titre: string, contenu: string) =>
  `<div style="background:#eff6ff;border-left:4px solid #3b82f6;padding:12px;border-radius:6px;margin:12px 0"><p style="margin:0 0 6px 0;font-weight:bold;color:#1e40af">💡 ${titre}</p><div>${contenu}</div></div>`;

const warn = (titre: string, contenu: string) =>
  `<div style="background:#fef2f2;border-left:4px solid #ef4444;padding:12px;border-radius:6px;margin:12px 0"><p style="margin:0 0 6px 0;font-weight:bold;color:#991b1b">⚠️ ${titre}</p><div>${contenu}</div></div>`;

const juris = (arret: string, principe: string) =>
  `<div style="background:#faf5ff;border-left:4px solid #a855f7;padding:12px;border-radius:6px;margin:12px 0;font-size:13px"><p style="margin:0 0 4px 0;font-weight:bold;color:#6b21a8">⚖️ Jurisprudence – ${arret}</p><p style="margin:0">${principe}</p></div>`;

export function getPaieChapters(): CourseChapter[] {
  return [
    {
      title: "Module 1 — Fondamentaux du droit du travail et de la paie",
      description: "Cadre légal, sources du droit, contrats, temps de travail, statuts particuliers — les bases indispensables avant de calculer une paie.",
      sections: [
        { title: "Le rôle et le périmètre du gestionnaire de paie", content: `${photo(IMG.bureau, "Environnement du gestionnaire de paie")}<p>Le <strong>gestionnaire de paie</strong> est le garant de la production mensuelle des bulletins et des déclarations sociales de l'entreprise. Il intervient à l'interface de <strong>quatre univers</strong> : les ressources humaines (contrats, absences, congés), le juridique (droit du travail, conventions collectives), la comptabilité (charges, provisions, OD de paie) et le contrôle de gestion sociale (KPI, masse salariale).</p><p><strong>Missions principales :</strong></p><ul><li>Collecter et fiabiliser les <em>éléments variables de paie</em> (EVP) : heures, primes, absences, tickets restaurant.</li><li>Établir les bulletins conformément à la loi, la convention collective et les accords d'entreprise.</li><li>Produire et transmettre la <strong>DSN mensuelle</strong> avant le 5 ou le 15 du mois M+1.</li><li>Gérer les événements du contrat : embauche (DPAE), arrêts, ruptures, STC.</li><li>Répondre aux salariés (bulletins, attestations, congés) avec pédagogie.</li><li>Assurer la <strong>veille juridique</strong> et anticiper les évolutions législatives.</li></ul><p><strong>Qualités requises :</strong> rigueur, discrétion absolue (données confidentielles au sens RGPD), sens du service, curiosité juridique, aisance avec les outils (Excel, logiciels de paie SaaS).</p>` },
        { title: "Les sources du droit du travail applicables à la paie", content: `<p>Le gestionnaire de paie s'appuie sur une hiérarchie de normes : <strong>Code du travail</strong>, <strong>convention collective</strong> (IDCC), <strong>accord de branche</strong>, <strong>accord d'entreprise</strong>, <strong>contrat de travail</strong>, <strong>usages</strong>. En cas de conflit, on retient la disposition la plus favorable au salarié (principe de faveur), sauf dérogation légale expresse issue des ordonnances Macron du 22 septembre 2017.</p><p>La <strong>convention collective</strong> (identifiée par son code IDCC à 4 chiffres) détermine notamment la <em>classification</em> (coefficient / niveau / échelon), le <em>salaire minimum conventionnel</em>, les <em>primes obligatoires</em> (ancienneté, 13ᵉ mois), la <em>période d'essai</em>, le <em>préavis</em> et les <em>indemnités de rupture</em>. Chaque bulletin doit mentionner l'IDCC applicable, sous peine de sanction (art. R. 3243-2 CT).</p>${info("À vérifier chaque année (janvier)", "<ul><li>Revalorisation du <strong>SMIC</strong> (au 1ᵉʳ janvier + revalorisation exceptionnelle en cours d'année si +2 % d'inflation).</li><li>Nouveau <strong>PMSS</strong> (plafond mensuel de la sécurité sociale) — <strong>3 925 € en 2026</strong>.</li><li>Nouveaux minima conventionnels (parution au JO).</li><li>Barèmes URSSAF frais professionnels, avantages en nature.</li><li>Taux AT/MP notifié par la CARSAT en décembre.</li></ul>")}${juris("Cass. soc., 10 juillet 2019, n° 17-31.639", "Une prime prévue par un usage d'entreprise s'impose à l'employeur tant qu'il ne l'a pas dénoncée régulièrement (information CSE + salariés concernés + délai de prévenance suffisant).")}` },
        { title: "Les différents contrats de travail", content: `<p>Le contrat de travail conditionne le calcul de la paie (assiette, cotisations, indemnités, mentions du bulletin). Panorama :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:13px"><tr style="background:#f0f0f0"><th>Contrat</th><th>Caractéristiques clés</th><th>Impact paie</th></tr><tr><td><strong>CDI</strong></td><td>Contrat de droit commun, sans terme</td><td>Standard, préavis en cas de rupture</td></tr><tr><td><strong>CDD</strong></td><td>Motif obligatoire écrit sous 2 jours ouvrables</td><td>+10 % prime de précarité (sauf exceptions)</td></tr><tr><td><strong>Apprentissage</strong></td><td>Alternance CFA/entreprise, âge 16-29 ans</td><td>Rémunération 27→100 % SMIC, exonération quasi-totale</td></tr><tr><td><strong>Professionnalisation</strong></td><td>Alternance, tout âge (dont demandeurs emploi ≥ 26 ans)</td><td>% SMIC ou minima conventionnel</td></tr><tr><td><strong>Intérim</strong></td><td>Contrat de mission via ETT</td><td>+10 % IFM + ICCP payés par l'ETT</td></tr><tr><td><strong>Temps partiel</strong></td><td>< 35 h/sem, répartition écrite</td><td>Heures complémentaires majorées 10 %/25 %</td></tr><tr><td><strong>Forfait jours</strong></td><td>Cadres autonomes, plafond 218 j/an</td><td>Pas d'heures sup, JRTT, entretien annuel</td></tr><tr><td><strong>CDI intérimaire</strong></td><td>CDI signé avec l'ETT</td><td>Garantie minimale mensuelle</td></tr></table>${warn("Requalification CDD → CDI", "Absence d'écrit dans les 2 jours ouvrables, absence de motif, dépassement de 18 mois (renouvellement inclus), succession sur le même poste sans délai de carence : le juge requalifie en CDI et le salarié bénéficie d'une indemnité au moins égale à 1 mois de salaire (art. L. 1245-2 CT).")}` },
        { title: "Temps de travail, heures supplémentaires et complémentaires", content: `<p>La <strong>durée légale</strong> est fixée à <strong>35 h/semaine</strong>, soit <strong>151,67 h/mois</strong> ou <strong>1 607 h/an</strong> (incluant la journée de solidarité). Au-delà : heures supplémentaires (temps plein) ou complémentaires (temps partiel).</p><p><strong>Majoration légale des heures sup :</strong></p><ul><li><strong>+25 %</strong> pour les 8 premières (36ᵉ → 43ᵉ heure hebdo).</li><li><strong>+50 %</strong> au-delà de la 43ᵉ heure.</li><li>Un accord d'entreprise ou de branche peut prévoir un taux différent, avec un <strong>minimum de 10 %</strong>.</li></ul><p><strong>Contingent annuel :</strong> 220 h par défaut. Au-delà, <strong>contrepartie obligatoire en repos</strong> (COR) : 50 % pour les entreprises ≤ 20 salariés, 100 % au-delà.</p><p><strong>Heures complémentaires (temps partiel) :</strong> +10 % dans la limite du 1/10ᵉ de la durée contractuelle, +25 % au-delà (dans la limite d'1/3 de la durée contractuelle, sans jamais atteindre 35 h).</p>${info("Exonération heures supplémentaires (loi TEPA / loi 2022)", "Depuis 2019, les heures sup sont <strong>exonérées d'impôt sur le revenu</strong> dans la limite de 7 500 €/an et bénéficient d'une <strong>réduction de cotisations salariales</strong> (11,31 % soit vieillesse + AGIRC-ARRCO). Côté employeur : déduction forfaitaire de 1,50 €/HS pour les entreprises < 20 salariés, 0,50 € entre 20 et 250.")}${exo("Calcul heures sup", "Un salarié à 35 h effectue 42 h une semaine (taux horaire 15 €). Calculez le brut supplémentaire dû.", "<p>7 heures supplémentaires à +25 % :</p><p>7 × 15 × 1,25 = <strong>131,25 €</strong> à ajouter au brut mensuel.</p><p>Réduction salariale (11,31 %) : ~14,85 € — le salarié récupère quasi le taux plein.</p>")}` },
        { title: "Statuts particuliers : cadres, apprentis, stagiaires, mandataires", content: `${photo(IMG.equipe, "Diversité des statuts")}<p>Chaque statut impose des règles spécifiques de paie :</p><ul><li><strong>Cadres au forfait jours</strong> : rémunération lissée, pas d'heures sup, mais convention individuelle écrite obligatoire, suivi de la charge, entretien annuel. En cas d'invalidité de la convention → rappel d'heures sup sur 3 ans.</li><li><strong>Apprentis</strong> : rémunération = % du SMIC selon âge/année (ex : 18-20 ans, 1ʳᵉ année = 43 % SMIC). Exonération totale de cotisations salariales sur la part ≤ 79 % SMIC. Pas d'IR sur la rémunération ≤ SMIC annuel.</li><li><strong>Stagiaires</strong> : gratification obligatoire si stage > 2 mois (44 j × 7 h). Montant : 4,35 €/h en 2026 (15 % PSSH). Exonérée de cotisations sous seuil, mais soumises au-delà.</li><li><strong>Mandataires sociaux</strong> (président SAS, gérant minoritaire SARL) : assimilés salariés, cotisations sur rémunération de mandat, pas de chômage.</li><li><strong>TNS</strong> (gérant majoritaire SARL, EI) : hors paie, cotisent à l'URSSAF-CGSS/SSI.</li></ul>${warn("Attention gratification stagiaire", "Si la gratification dépasse le seuil (15 % PSSH × heures présence), l'excédent devient un salaire soumis à toutes les cotisations. Contrôle URSSAF fréquent depuis 2023.")}` },
      ],
    },
    {
      title: "Module 2 — Construire un bulletin de paie clair et conforme",
      description: "De la structure du bulletin simplifié à la ventilation des rubriques : brut, cotisations, net imposable, net à payer, net social.",
      sections: [
        { title: "Structure du bulletin de paie simplifié (arrêté 25 février 2016, modifié 2023)", content: `${photo(IMG.bulletin, "Bulletin de paie simplifié")}<p>Depuis 2018 (et enrichi en 2023 avec le <strong>montant net social</strong>), le bulletin est standardisé en <strong>5 blocs</strong> :</p><ol><li><strong>En-tête</strong> : identité employeur (SIRET, code APE, adresse, URSSAF de rattachement, IDCC), identité salarié (nom, prénom, poste, classification), période, N° matricule.</li><li><strong>Rémunération</strong> : salaire de base, heures normales/supplémentaires, primes, avantages en nature, indemnités.</li><li><strong>Cotisations et contributions</strong> regroupées par risque : santé, retraite, chômage, autres contributions (FNAL, versement mobilité, formation, apprentissage, dialogue social).</li><li><strong>Net à payer avant impôt / Net imposable / Impôt PAS / Net à payer</strong>.</li><li><strong>Cumuls annuels</strong> (brut, net, PAS), <strong>montant net social</strong>, mentions légales, congés/RTT acquis et pris.</li></ol><p><strong>Mentions obligatoires supplémentaires</strong> (art. R. 3243-1 CT) : convention collective + IDCC, référence organisme de collecte URSSAF, allègement de cotisations employeur (réduction générale), mention du droit de conservation sans limite de durée par le salarié.</p>${info("Le montant net social (depuis juillet 2023)", "Nouvelle ligne obligatoire = revenu de référence pour l'attribution de la <strong>Prime d'activité</strong> et du <strong>RSA</strong>. Formule : brut soumis à cotisations − cotisations obligatoires (salarié et part employeur mutuelle) + IJSS + avantages en nature. Doit apparaître clairement sur le bulletin.")}` },
        { title: "Du brut au net : mécanique de calcul détaillée", content: `${photo(IMG.calcul, "Du brut au net")}<p><strong>Étapes canoniques :</strong></p><ol><li><strong>Salaire de base</strong> = taux horaire × heures contractuelles (ex : 12,50 € × 151,67 h = <strong>1 895,88 €</strong>).</li><li>+ heures supplémentaires majorées, primes soumises, avantages en nature.</li><li>= <strong>BRUT</strong> (base de calcul des cotisations).</li><li>− cotisations salariales : santé complémentaire, retraite Sécu (6,90 % + 0,40 %), AGIRC-ARRCO (3,15 % T1 / 8,64 % T2), CEG (0,86 % / 1,08 %), APEC (0,024 % cadres), CSG déductible (6,80 % × 98,25 %), CSG + CRDS non déductibles (2,90 % × 98,25 %).</li><li>= <strong>Net à payer avant impôt</strong>.</li><li>− prélèvement à la source (PAS) selon taux transmis par la DGFiP (personnalisé, neutre ou individualisé).</li><li>= <strong>Net à payer</strong>.</li></ol>${info("Repères 2026", "<ul><li>Cotisations salariales : ~22 % du brut pour un non-cadre, ~25 % pour un cadre.</li><li>Cotisations patronales : ~42 % du brut (peut descendre à ~15 % au SMIC via la réduction générale).</li><li>Coût total employeur = brut × 1,42 environ.</li><li>Rapport net/brut ≈ 0,78 non-cadre, 0,75 cadre.</li></ul>")}${exo("Bulletin SMIC 2026", "Un salarié au SMIC (11,88 €/h × 151,67 h) sans primes ni HS. Calculez le brut, estimez cotisations salariales (22 %), puis le net avant impôt (taux PAS neutre 0 % car en dessous du seuil).", "<p>Brut = 11,88 × 151,67 = <strong>1 801,84 €</strong></p><p>Cotisations salariales ~22 % = 396,40 €</p><p>Net avant impôt ≈ <strong>1 405,44 €</strong> — au niveau du <strong>SMIC net</strong> officiel.</p><p>PAS = 0 € (sous seuil), Net à payer = 1 405,44 €.</p>")}` },
        { title: "Traitements particuliers : avantages en nature, frais professionnels, primes", content: `<p><strong>Avantages en nature (AN)</strong> — biens ou services fournis par l'employeur à moindre coût :</p><ul><li><strong>Nourriture</strong> : forfait URSSAF 5,45 €/repas en 2026 (10,90 €/jour).</li><li><strong>Logement</strong> : barème 8 tranches selon rémunération et nombre de pièces (67,90 € à 906,60 €/mois).</li><li><strong>Véhicule</strong> : forfait 9 % (ou 12 % si carburant employeur) du coût d'achat TTC pour véhicule < 5 ans, sinon 30 % de la location + 40 % carburant. Ou valeur réelle.</li><li><strong>NTIC</strong> (téléphone, PC) : 10 % du coût d'achat.</li></ul><p>Les AN sont <strong>ajoutés au brut</strong>, soumis à cotisations et impôt, puis <strong>déduits du net</strong> (l'employeur ne verse pas d'espèces pour cette part).</p><p><strong>Frais professionnels</strong> — dépenses engagées par le salarié pour l'entreprise :</p><ul><li>Indemnisation exonérée dans la limite des <strong>barèmes URSSAF</strong> (repas d'affaires 21,10 €, grand déplacement 20,70 € repas + 74,30 € logement Paris, restauration sur lieu de travail 7,40 €).</li><li>Deux modes : <em>forfait URSSAF</em> (pas de justificatif) ou <em>frais réels</em> (avec justificatifs).</li><li>Titre restaurant : exonéré ≤ 7,26 € (contribution employeur 50-60 %).</li></ul><p><strong>Primes</strong> — à distinguer :</p><ul><li><em>Primes soumises</em> : 13ᵉ mois, prime d'ancienneté, prime d'objectifs, prime de vacances → cotisations complètes.</li><li><em>Prime Partage de la Valeur (PPV)</em> : plafonds 3 000 € (6 000 € si accord d'intéressement) exonérée de cotisations salariales et patronales pour les < 3 SMIC (depuis 2024, imposable et soumise CSG/CRDS sauf entreprises < 50 salariés).</li><li><em>Prime de partage des profits</em> : intéressement et participation → soumis CSG/CRDS + forfait social.</li></ul>${warn("Requalification par l'URSSAF", "Un remboursement forfaitaire non justifié dépassant les barèmes est requalifié en salaire → cotisations et pénalités de retard sur 3 ans.")}` },
        { title: "Le prélèvement à la source (PAS) en pratique", content: `<p>Depuis le <strong>1er janvier 2019</strong>, l'impôt sur le revenu est prélevé mensuellement sur les salaires. L'employeur est <strong>collecteur pour le compte de la DGFiP</strong>.</p><p><strong>Fonctionnement :</strong></p><ol><li>Le taux est transmis chaque mois par la DGFiP via le <strong>CRM</strong> (Compte-Rendu Métier) suite à la DSN.</li><li>3 taux possibles : personnalisé (défaut), neutre (grille tarifaire par défaut), individualisé (option couple).</li><li>Assiette : <strong>net imposable</strong> (net à payer avant impôt + CSG/CRDS non déductibles + part patronale mutuelle imposable).</li><li>Prélèvement affiché sur une ligne dédiée du bulletin.</li></ol>${info("Taux neutre (grille janvier 2026)", "Utilisé si aucun taux transmis par DGFiP (nouvel embauché, refus du salarié). Grille progressive de 0 % (net imposable < 1 620 €) à 43 % (> 51 240 €/mois). L'employeur doit régulariser dès réception du taux réel.")}${warn("Sanctions employeur", "Non-reversement du PAS = amende de 5 % du prélèvement omis (min 250 €). Divulgation du taux à un tiers = 10 000 € par salarié.")}` },
        { title: "Contrôle du bulletin : check-list du gestionnaire", content: `${photo(IMG.documents, "Contrôle qualité du bulletin")}<p>Avant validation et envoi, chaque bulletin doit passer une <strong>check-list qualité</strong> :</p><ol><li>✅ Identité complète employeur/salarié + IDCC + classification.</li><li>✅ Période de paie et date de paiement.</li><li>✅ Heures normales × taux = salaire de base cohérent.</li><li>✅ Heures sup avec bonnes majorations (25 % / 50 %).</li><li>✅ Absences (maladie, CP, RTT) correctement décomptées.</li><li>✅ Assiettes cotisations : brut / T1 / T2 / CSG (98,25 %).</li><li>✅ Réduction générale (Fillon) calculée si salaire < 1,6 SMIC.</li><li>✅ Net imposable = ligne cohérente pour le PAS.</li><li>✅ Ligne <strong>Montant net social</strong> présente.</li><li>✅ Cumuls annuels mis à jour (brut, net, PAS, CP acquis/pris).</li><li>✅ Mentions légales de bas de bulletin.</li></ol>${exo("Erreur classique", "Sur un bulletin, l'assiette CSG affichée est de 1 800 € pour un brut de 1 800 €. Que faut-il vérifier ?", "<p>L'assiette CSG/CRDS doit être <strong>98,25 % du brut</strong> (abattement de 1,75 % pour frais professionnels), soit 1 800 × 0,9825 = <strong>1 768,50 €</strong>. Il y a donc une erreur de paramétrage. À corriger immédiatement pour éviter un rappel URSSAF.</p>")}` },
      ],
    },
    {
      title: "Module 3 — Cotisations sociales, DSN et déclarations",
      description: "Assiettes, taux, tranches, logique URSSAF, allègements Fillon, DSN mensuelle et événementielle.",
      sections: [
        { title: "Assiettes et tranches (PMSS 2026 = 3 925 €)", content: `${photo(IMG.calcul, "Calcul des cotisations sociales")}<p>Les cotisations se calculent sur des <strong>assiettes plafonnées ou déplafonnées</strong> :</p><ul><li><strong>T1 (tranche 1)</strong> : 0 → 1 PMSS = <strong>3 925 €</strong>.</li><li><strong>T2 (tranche 2)</strong> : 1 → 8 PMSS = <strong>31 400 €</strong> pour AGIRC-ARRCO.</li><li><strong>TA / TB / TC</strong> : anciennes tranches encore utilisées pour la prévoyance/mutuelle (TA=1 PMSS, TB=1-4 PMSS, TC=4-8 PMSS).</li><li><strong>Déplafonné</strong> : totalité du brut (maladie, CSG, CRDS, allocations familiales, accidents du travail, FNAL).</li></ul><p>La <strong>CSG et CRDS</strong> s'appliquent sur <strong>98,25 %</strong> du brut (abattement 1,75 % pour frais professionnels) dans la limite de 4 PMSS, puis 100 % au-delà.</p><p><strong>Taux 2026 :</strong> CSG déductible 6,80 %, CSG non déductible 2,40 %, CRDS 0,50 % (total salarié 9,70 %).</p>${info("Proratisation du plafond", "Pour un temps partiel ou une entrée/sortie en cours de mois, le PMSS est proraté : PMSS × (h payées / 151,67). Sinon, sur-cotisation AGIRC-ARRCO T2 injustifiée.")}` },
        { title: "Panorama des cotisations (part salariale / part patronale)", content: `<table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:12px"><tr style="background:#f0f0f0"><th>Risque</th><th>Salarié</th><th>Employeur</th><th>Assiette</th></tr><tr><td>Maladie-maternité</td><td>—</td><td>7,00 % (13,00 % si > 2,5 SMIC)</td><td>Brut</td></tr><tr><td>Vieillesse plafonnée</td><td>6,90 %</td><td>8,55 %</td><td>T1</td></tr><tr><td>Vieillesse déplafonnée</td><td>0,40 %</td><td>2,02 %</td><td>Brut</td></tr><tr><td>Allocations familiales</td><td>—</td><td>3,45 % (5,25 % si > 3,5 SMIC)</td><td>Brut</td></tr><tr><td>AT/MP</td><td>—</td><td>Variable (0,7 % à 8 %, notifié CARSAT)</td><td>Brut</td></tr><tr><td>AGIRC-ARRCO T1</td><td>3,15 %</td><td>4,72 %</td><td>T1</td></tr><tr><td>AGIRC-ARRCO T2</td><td>8,64 %</td><td>12,95 %</td><td>T2</td></tr><tr><td>CEG T1 / T2</td><td>0,86 % / 1,08 %</td><td>1,29 % / 1,62 %</td><td>T1 / T2</td></tr><tr><td>CET (> 1 PMSS)</td><td>0,14 %</td><td>0,21 %</td><td>T1 + T2</td></tr><tr><td>APEC (cadres)</td><td>0,024 %</td><td>0,036 %</td><td>TA + TB</td></tr><tr><td>Chômage</td><td>—</td><td>4,05 %</td><td>≤ 4 PMSS</td></tr><tr><td>AGS</td><td>—</td><td>0,25 %</td><td>≤ 4 PMSS</td></tr><tr><td>CSG déductible</td><td>6,80 %</td><td>—</td><td>98,25 % brut</td></tr><tr><td>CSG + CRDS non déd.</td><td>2,90 %</td><td>—</td><td>98,25 % brut</td></tr><tr><td>FNAL</td><td>—</td><td>0,10 % (< 50 sal.) / 0,50 %</td><td>Brut / ≤ 1 PMSS</td></tr><tr><td>Versement mobilité</td><td>—</td><td>0 % à 2,95 % (selon zone)</td><td>Brut</td></tr><tr><td>Formation prof.</td><td>—</td><td>0,55 % / 1 %</td><td>Brut</td></tr><tr><td>Apprentissage (CUFPA)</td><td>—</td><td>0,68 %</td><td>Brut</td></tr></table>` },
        { title: "La réduction générale de cotisations (ex-Fillon)", content: `<p>Créée en 2003, la <strong>réduction générale</strong> allège les cotisations patronales pour les salaires < 1,6 SMIC. C'est le principal dispositif de réduction du coût du travail en France.</p><p><strong>Formule 2026 :</strong></p><p style="text-align:center;font-family:monospace;background:#f3f4f6;padding:8px;border-radius:6px">Coef = (T / 0,6) × (1,6 × SMIC annuel / rému annuelle brute − 1)</p><p>Avec <strong>T</strong> = 0,3194 (entreprises < 50 sal.) ou 0,3234 (≥ 50 sal.).</p><p>La réduction = Coef × rému brute. Coefficient plafonné à T (au SMIC exact) et nul dès 1,6 SMIC.</p>${exo("Calcul réduction générale", "Salarié à 1 900 € brut/mois (< 20 salariés). SMIC mensuel 1 801,84 €. Calculez le coefficient et le montant de la réduction.", "<p>Rému annuelle = 1 900 × 12 = 22 800 €</p><p>SMIC annuel × 1,6 = 1 801,84 × 12 × 1,6 = 34 595,33 €</p><p>Coef = (0,3194 / 0,6) × (34 595,33 / 22 800 − 1) = 0,5323 × 0,5173 = <strong>0,2754</strong></p><p>Réduction annuelle = 0,2754 × 22 800 = <strong>6 279 €</strong>, soit ~523 €/mois d'économie de cotisations patronales.</p>")}${warn("Contrôle URSSAF", "Erreur de formule fréquente : oubli du plafonnement à 1,6 SMIC, mauvaise prise en compte des HS/HC dans le SMIC annuel. Utiliser le calculateur officiel URSSAF pour sécuriser.")}` },
        { title: "La DSN : Déclaration Sociale Nominative", content: `${photo(IMG.urssaf, "DSN URSSAF mensuelle")}<p>La <strong>DSN</strong>, généralisée depuis 2017, est le <strong>canal unique</strong> de déclaration mensuelle des données sociales : URSSAF, AGIRC-ARRCO, France Travail, prévoyance, DGFiP (PAS), Caisses de congés du BTP.</p><p><strong>Échéances mensuelles :</strong></p><ul><li><strong>Le 5</strong> du mois M+1 : entreprises ≥ 50 salariés avec décalage de paie.</li><li><strong>Le 15</strong> du mois M+1 : toutes les autres entreprises.</li></ul><p><strong>DSN événementielles</strong> (5 jours après l'événement) :</p><ul><li>Arrêt de travail (maladie, AT, maternité).</li><li>Reprise anticipée d'activité.</li><li>Fin de contrat (remplace l'ancienne attestation Pôle emploi papier).</li></ul><p><strong>Contrôles bloquants</strong> (rejet DSN) : cohérence brut ↔ plafond, assiettes CSG, taux de cotisation non conformes, N° SIRET/NIC invalide, doublon d'individu.</p>${info("Bonnes pratiques DSN", "<ul><li>Paramétrage rigoureux du logiciel (Silae, Sage, Cegid, PayFit, ADP, EBP).</li><li>Rapprochement mensuel : DSN ↔ bulletins ↔ comptabilité (compte 641, 645, 645X, 43X).</li><li>Analyse systématique du CRM (compte-rendu métier) : anomalies bloquantes ou signalées.</li><li>Archivage 6 ans minimum (URSSAF) ou 10 ans (comptabilité).</li></ul>")}${warn("Sanctions retard DSN", "Retard de dépôt : 1,5 % du PMSS par salarié et par mois (58,88 € en 2026 !). Erreur non corrigée dans les 30 jours : 0,33 % du PMSS par salarié.")}` },
        { title: "Les déclarations annuelles récapitulatives", content: `<p>Bien que la DSN mensuelle ait absorbé la plupart des déclarations, il subsiste des obligations annuelles :</p><ul><li><strong>DOETH</strong> (Déclaration Obligatoire d'Emploi des Travailleurs Handicapés) : intégrée à la DSN de février (entreprises ≥ 20 salariés). Contribution AGEFIPH si < 6 % de BOETH.</li><li><strong>Taxe d'apprentissage (CUFPA)</strong> : solde 13 % à verser via SOLTéA avant le 15 mai.</li><li><strong>Participation formation continue</strong> : versement OPCO avant le 1er mars (0,55 % ou 1 % selon effectif).</li><li><strong>Effort construction (PEEC)</strong> : 0,45 % pour les ≥ 50 salariés, à verser à Action Logement.</li><li><strong>Taxe sur les salaires</strong> : entreprises non assujetties à la TVA (mutuelles, associations, holdings). Barème progressif 4,25 % → 20 %.</li><li><strong>Bilan social</strong> : entreprises ≥ 300 salariés, communiqué au CSE.</li></ul>` },
      ],
    },
    {
      title: "Module 4 — Absences, congés payés et indemnités journalières",
      description: "Décompte des congés, maintien de salaire, subrogation IJSS, calcul de retenue absence, congés spéciaux.",
      sections: [
        { title: "Congés payés : acquisition, décompte, indemnisation", content: `<p><strong>Acquisition :</strong> <strong>2,5 jours ouvrables</strong> par mois travaillé, soit <strong>30 jours ouvrables/an</strong> (ou 25 jours ouvrés). Période de référence : <strong>1er juin N-1 → 31 mai N</strong> (sauf accord d'entreprise différent).</p><p><strong>Décompte :</strong></p><ul><li>Jours ouvrables : lundi au samedi inclus (sauf jours fériés chômés).</li><li>Jours ouvrés : lundi au vendredi (5 j/sem).</li><li>Le 1er jour décompté est le 1er jour ouvrable où le salarié aurait dû travailler.</li></ul><p><strong>Deux méthodes d'indemnisation</strong> — la plus favorable au salarié s'applique (art. L. 3141-24 CT) :</p><ol><li><strong>Maintien de salaire</strong> : le salarié perçoit son salaire habituel comme s'il avait travaillé.</li><li><strong>1/10ᵉ</strong> de la rémunération brute perçue sur la période de référence (juin N-1 → mai N).</li></ol>${info("Congés payés et arrêt maladie (nouveauté 2024)", "Suite à la mise en conformité avec le droit européen (arrêts CJUE + Cass. soc. 13 septembre 2023), les salariés en <strong>arrêt maladie non professionnelle</strong> acquièrent aussi des CP : 2 jours ouvrables/mois, plafonnés à 24 jours/an. Rétroactivité possible sur 3 ans (2 ans si toujours dans l'entreprise). L'employeur doit informer le salarié dans le mois suivant la reprise.")}${juris("CJUE, 20 janvier 2009, Schultz-Hoff", "Un salarié en arrêt maladie continue d'acquérir ses congés payés — principe imposé à la France en 2024 après 15 ans de résistance.")}` },
        { title: "Retenue absence : méthodes légales", content: `<p>Trois méthodes tolérées, la <strong>plus favorable au salarié</strong> doit être appliquée :</p><ol><li><strong>Heures réelles du mois</strong> — retenue = brut × (h absence / h travaillées du mois).</li><li><strong>Jours ouvrés du mois</strong> — retenue = brut × (j absence / j ouvrés du mois).</li><li><strong>Moyennisation mensuelle (30ᵉ)</strong> — attention : souvent la <em>moins</em> favorable.</li></ol>${exo("Retenue absence", "Un salarié gagne 2 200 € brut pour 151,67 h. Il est absent 14 h en mars (176 h ouvrées). Calculez la retenue selon la méthode des heures réelles puis des jours ouvrés (mars 2026 = 22 jours ouvrés, absence = 2 jours).", "<p><strong>Heures réelles :</strong> 2 200 × (14 / 176) = <strong>175,00 €</strong> de retenue → salaire versé 2 025,00 €.</p><p><strong>Jours ouvrés :</strong> 2 200 × (2 / 22) = <strong>200,00 €</strong> → salaire versé 2 000,00 €.</p><p>La méthode <em>heures réelles</em> est plus favorable au salarié : c'est elle qui doit être appliquée.</p>")}` },
        { title: "IJSS, subrogation, prévoyance", content: `<p><strong>Indemnités Journalières de Sécurité Sociale (IJSS)</strong> pour arrêt maladie :</p><ul><li><strong>Franchise :</strong> 3 jours (sauf accident du travail : 0 jour, maladie professionnelle : 0 jour, arrêt > 6 mois : 0 jour).</li><li><strong>Montant :</strong> 50 % du salaire journalier de base (SJB = (S1+S2+S3) / 91,25 avec S = salaires bruts 3 derniers mois), plafonné à <strong>1,4 SMIC</strong>, soit ~52 €/jour max en 2026.</li><li><strong>Majoration :</strong> +2/3 dès 30 jours d'arrêt si 3 enfants à charge.</li></ul><p><strong>Maintien de salaire employeur</strong> (Loi Mensualisation art. D. 1226-1) obligatoire dès <strong>1 an d'ancienneté</strong> :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:13px"><tr style="background:#f0f0f0"><th>Ancienneté</th><th>90 %</th><th>66,66 %</th></tr><tr><td>1-5 ans</td><td>30 j</td><td>30 j</td></tr><tr><td>6-10 ans</td><td>40 j</td><td>40 j</td></tr><tr><td>11-15 ans</td><td>50 j</td><td>50 j</td></tr><tr><td>16-20 ans</td><td>60 j</td><td>60 j</td></tr><tr><td>26-30 ans</td><td>80 j</td><td>80 j</td></tr><tr><td>≥ 31 ans</td><td>90 j</td><td>90 j</td></tr></table><p><strong>Subrogation</strong> : l'employeur perçoit les IJSS à la place du salarié et lui verse son salaire habituel. Traitement en paie : IJSS <em>brutes</em> déduites du brut (car non soumises à cotisations), IJSS <em>nettes</em> ajoutées au net (soumises seulement à CSG/CRDS à taux réduit 6,20 % + 0,50 %).</p>${warn("Attention DSN évt", "L'arrêt de travail doit être déclaré via DSN événementielle sous <strong>5 jours</strong>. À défaut : retard de traitement du dossier par la CPAM et rupture du complément de salaire.")}` },
        { title: "Congés spéciaux : famille, formation, événements", content: `<p>Le Code du travail et les conventions collectives prévoient de nombreux <strong>congés spéciaux</strong> :</p><ul><li><strong>Mariage / PACS</strong> : 4 jours (salarié), 1 jour (enfant).</li><li><strong>Naissance / adoption</strong> : 3 jours pour le second parent.</li><li><strong>Congé paternité</strong> : 25 jours calendaires (32 si naissance multiple), à prendre dans les 6 mois. Indemnisation IJSS.</li><li><strong>Décès conjoint/enfant/parent</strong> : 3 à 12 jours selon lien.</li><li><strong>Enfant malade</strong> : 3 j/an (5 si enfant < 1 an ou charge de 3 enfants).</li><li><strong>Congé pour proche aidant</strong> : 3 mois renouvelables (jusqu'à 1 an), avec AJPA (65 €/j).</li><li><strong>Congé parental d'éducation</strong> : jusqu'aux 3 ans de l'enfant.</li><li><strong>Congé de formation</strong> (CPF de transition, VAE, bilan de compétences).</li></ul>${info("Congé paternité 2026", "Depuis juillet 2021, la durée totale est de <strong>28 jours</strong> (3 jours employeur + 25 jours IJSS). Fractionnement possible en 2 périodes, dont 7 jours obligatoires immédiatement après la naissance. Non-respect = amende de 7 500 € pour l'employeur.")}` },
      ],
    },
    {
      title: "Module 5 — Rupture du contrat et solde de tout compte",
      description: "Préavis, indemnités, portabilité, documents de fin de contrat, régime social et fiscal des indemnités.",
      sections: [
        { title: "Types de rupture et indemnités associées", content: `${photo(IMG.contrat, "Solde de tout compte")}<table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:13px"><tr style="background:#f0f0f0"><th>Type de rupture</th><th>Indemnité</th><th>Régime social/fiscal</th></tr><tr><td>Démission</td><td>Aucune (sauf licenciement provoqué)</td><td>—</td></tr><tr><td>Licenciement économique</td><td>ILE conventionnelle ≥ légale (+ éventuel CSP)</td><td>Exonéré dans limites (2 PASS ou 6 PASS si > 10 ans)</td></tr><tr><td>Licenciement personnel</td><td>ILC légale : 1/4 mois × ancienneté (0-10 ans), 1/3 au-delà</td><td>Exonéré cotis. dans limites, imposable si > barème</td></tr><tr><td>Licenciement faute grave/lourde</td><td>Aucune indemnité de licenciement ni préavis</td><td>—</td></tr><tr><td>Rupture conventionnelle</td><td>= ILC minimum (souvent négociée à la hausse)</td><td>Exonéré dans limites + <strong>forfait social 30 % pat.</strong></td></tr><tr><td>Rupture conv. collective (RCC)</td><td>Accord collectif</td><td>Régime de faveur, exo partielle</td></tr><tr><td>Fin de CDD</td><td>Prime de précarité <strong>10 %</strong> (sauf CDD saisonnier/senior/apprenti)</td><td>Soumis cotisations</td></tr><tr><td>Fin période d'essai</td><td>Aucune indemnité (respect préavis)</td><td>—</td></tr><tr><td>Retraite (départ volontaire)</td><td>Selon convention (1/2 mois → 2 mois)</td><td>Soumis cotisations</td></tr><tr><td>Mise à la retraite (employeur)</td><td>= ILC minimum</td><td>Exonéré cotis. + contribution 50 %</td></tr></table>${info("Barème d'exonération 2026", "Indemnité de licenciement exonérée dans la limite la plus élevée entre : 2 fois la rémunération brute annuelle N-1, 50 % de l'indemnité totale, ou <strong>2 PASS</strong> (94 200 €). Au-delà de 6 PASS (282 600 €) → totalement soumise à cotisations et impôt.")}` },
        { title: "Le préavis : durée, dispense, indemnité", content: `<p>Le <strong>préavis</strong> est la période de travail obligatoire entre la notification de la rupture et la sortie effective des effectifs.</p><p><strong>Durée légale (licenciement autre que faute grave) :</strong></p><ul><li>Ancienneté < 6 mois : préavis conventionnel/usages.</li><li>6 mois → 2 ans : <strong>1 mois</strong>.</li><li>≥ 2 ans : <strong>2 mois</strong>.</li></ul><p><strong>Démission :</strong> selon convention collective (souvent 1 à 3 mois cadre).</p><p><strong>Dispense de préavis :</strong></p><ul><li>À l'initiative du <strong>salarié</strong> : préavis non payé.</li><li>À l'initiative de l'<strong>employeur</strong> : <strong>indemnité compensatrice de préavis</strong> (ICP) versée = salaire qu'aurait perçu le salarié en travaillant. Soumise à cotisations comme un salaire.</li></ul>${juris("Cass. soc., 18 nov. 2020, n° 19-13.599", "L'indemnité compensatrice de préavis doit inclure toutes les primes que le salarié aurait perçues (13ᵉ mois au prorata, prime d'ancienneté). Sinon rappel.")}` },
        { title: "Solde de tout compte : composants et documents", content: `<p>Le <strong>solde de tout compte (STC)</strong> regroupe tous les éléments dus au salarié à son départ :</p><ol><li>Salaire du mois de départ au prorata des jours travaillés.</li><li><strong>Indemnité compensatrice de préavis (ICP)</strong> si non exécuté à la demande employeur.</li><li><strong>Indemnité compensatrice de congés payés (ICCP)</strong> : 10 % de la rémunération brute perçue depuis le début de la période N-1 non pris + N.</li><li>Indemnité de rupture (ILC / rupture conv. / précarité CDD / départ retraite).</li><li>Prime au prorata (13ᵉ mois, ancienneté, objectifs).</li><li>Épargne salariale débloquée le cas échéant (intéressement, participation).</li><li>Reprise éventuelle d'un trop-perçu ou d'un prêt.</li></ol><p><strong>Documents obligatoires à remettre :</strong></p><ul><li><strong>Bulletin de paie du STC</strong> (avec ligne indemnité clairement identifiée).</li><li><strong>Certificat de travail</strong> (art. L. 1234-19) : dates, nature emploi, portabilité mutuelle/prévoyance.</li><li><strong>Attestation France Travail (ex-Pôle emploi)</strong> — désormais transmise via DSN événementielle "fin de contrat".</li><li><strong>Reçu pour solde de tout compte</strong> — signé par le salarié, <strong>dénonçable dans les 6 mois</strong> pour les sommes qui y sont mentionnées (art. L. 1234-20).</li><li><strong>État récapitulatif épargne salariale</strong> (livret d'épargne salariale, transferts PERCO).</li></ul>${warn("Sanctions retard STC", "Retard de remise = 6 mois d'emprisonnement + 7 500 € (attestation Pôle emploi). Congés payés non versés = rappel + intérêts + dommages-intérêts.")}` },
        { title: "Portabilité prévoyance et mutuelle", content: `<p>À la fin du contrat (<strong>hors faute lourde uniquement</strong>), le salarié éligible à France Travail bénéficie de la <strong>portabilité</strong> de la mutuelle et de la prévoyance :</p><ul><li>Durée = durée du dernier contrat de travail, dans la limite de <strong>12 mois</strong>.</li><li>Financement <strong>mutualisé</strong> : déjà inclus dans les cotisations des salariés actifs.</li><li>Formalités : cocher la case portabilité sur le certificat de travail, notifier l'organisme assureur, remettre les coordonnées au salarié.</li><li>Le salarié doit fournir chaque mois son justificatif d'indemnisation France Travail.</li></ul>${info("Cas particulier : Loi Évin", "Après les 12 mois de portabilité, l'ex-salarié peut souscrire à titre individuel à la mutuelle de l'ex-employeur (Loi Évin). Tarifs plafonnés : 100 % de la cotisation en année 1, 125 % en année 2, 150 % à partir de l'année 3.")}` },
        { title: "Régime social et fiscal des indemnités de rupture", content: `<p>Chaque euro d'indemnité doit être analysé selon <strong>3 régimes</strong> distincts :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:12px"><tr style="background:#f0f0f0"><th>Régime</th><th>Seuil d'exonération</th></tr><tr><td>Cotisations sociales</td><td>2 PASS = 94 200 € en 2026 (dans la limite du montant exonéré d'IR)</td></tr><tr><td>CSG/CRDS</td><td>Fraction ≤ minimum légal ou conventionnel</td></tr><tr><td>Impôt sur le revenu</td><td>Plus élevé entre : minimum légal/conventionnel, 2× rému N-1, 50 % du total (max 6 PASS)</td></tr></table><p><strong>Cas particuliers :</strong></p><ul><li><strong>Rupture conventionnelle</strong> : indemnité + forfait social patronal de 30 % (mise en place 2013).</li><li><strong>Départ à la retraite volontaire</strong> : soumise à cotisations en totalité.</li><li><strong>Mise à la retraite employeur</strong> : contribution patronale spécifique de 50 %.</li></ul>${exo("Régime indemnité rupture conv.", "Salarié 8 ans d'ancienneté, salaire mensuel 3 000 €. Indemnité rupture conv. négociée = 12 000 €. ILC légale = 3 000 × 1/4 × 8 = 6 000 €. Analyse fiscale et sociale ?", "<p><strong>Cotisations :</strong> exonération dans la limite du minimum légal (6 000 €). Les 6 000 € au-delà sont exonérés jusqu'à 2 PASS. Ici 12 000 € < 2 PASS → <strong>totalement exonéré de cotisations</strong>.</p><p><strong>CSG/CRDS :</strong> soumis au-delà du minimum légal → 6 000 € × 9,70 % = <strong>582 €</strong> de CSG/CRDS.</p><p><strong>IR :</strong> Le plus favorable entre : 6 000 € (min légal) ou 2 × 36 000 € = 72 000 € ou 50 % × 12 000 = 6 000 €. Exonération 12 000 € intégralement (< 2 PASS).</p><p><strong>Forfait social patronal 30 %</strong> = 3 600 € à la charge employeur.</p>")}` },
        { title: "Transaction, protocole transactionnel et rappels de salaire", content: `<p>Une <strong>transaction</strong> (art. 2044 C. civ.) intervient <em>après</em> la rupture pour éteindre un litige. Elle suppose des <strong>concessions réciproques</strong> et fait obstacle à toute action en justice ultérieure sur les points transigés.</p><p><strong>Traitement paie de l'indemnité transactionnelle :</strong></p><ul><li>Analyse en <strong>2 fractions</strong> : nature indemnitaire (préjudice → exonérée dans les mêmes limites que l'ILC) et nature salariale (rappels HS, primes → soumise intégralement).</li><li>Bulletin de paie séparé, mention explicite du protocole.</li><li>Déclaration en DSN "rappel sur période antérieure" pour la part salariale.</li><li>Régularisation des CP/RTT non pris.</li></ul>${juris("Cass. soc., 21 mai 2014, n° 12-26.930", "L'URSSAF peut requalifier une transaction en salaire si l'employeur ne prouve pas la nature indemnitaire (préjudice moral, réparation). Documenter par écrit dans le protocole les postes de préjudice.")}${warn("Rappels de salaire (prud'hommes, rappel URSSAF)", "Les rappels de salaire ordonnés par le juge doivent : (1) être rattachés à la période d'origine pour le calcul des plafonds T1/T2, (2) figurer sur un bulletin de rappel, (3) être déclarés en DSN mois M+1, (4) intégrer intérêts légaux (rémunération financière soumise CSG/CRDS uniquement).")}` },
        { title: "Cas particulier : décès du salarié — traitement paie et succession", content: `<p>Le décès du salarié met fin automatiquement au contrat. Le gestionnaire de paie doit produire un <strong>STC particulier</strong> :</p><ol><li>Salaire au prorata jusqu'au jour du décès inclus.</li><li>Indemnité compensatrice de CP acquis non pris.</li><li>Prime au prorata (13ᵉ mois, ancienneté).</li><li><strong>Aucune ILC</strong> ni indemnité de préavis (rupture par le fait du salarié).</li><li>Capital décès prévoyance (versé à la famille selon clause bénéficiaire).</li><li>Rente éducation, rente conjoint le cas échéant.</li></ol><p><strong>Bénéficiaires du STC :</strong> versement à la <strong>succession</strong>, sur présentation d'un acte de notoriété (notaire). Sommes exonérées de cotisations, mais imposables au titre des droits de succession (article 774 CGI).</p>${info("Formalités URSSAF/CPAM", "Déclarer le décès en DSN événementielle sous 5 jours. Prévenir la CPAM (capital décès de 3 738 € pour ayants droit d'un salarié ou demandeur d'emploi en 2026). Informer la caisse de retraite et la prévoyance dans les 15 jours.")}` },
      ],
    },
    {
      title: "Module 6 — Contrôles, veille juridique et posture professionnelle",
      description: "Contrôle URSSAF, tableaux de bord paie, veille sociale, RGPD, éthique et outils du gestionnaire.",
      sections: [
        { title: "Anticiper et gérer un contrôle URSSAF", content: `${photo(IMG.reunion, "Contrôle URSSAF")}<p>L'URSSAF peut contrôler l'entreprise sur les <strong>3 dernières années</strong> (5 en cas de travail dissimulé). Le contrôle est annoncé par un <strong>avis de passage</strong> (au moins 30 jours à l'avance) accompagné de la <strong>Charte du cotisant contrôlé</strong>.</p><p><strong>Déroulement type :</strong></p><ol><li>Réception de l'avis de contrôle (avec liste indicative des documents à préparer).</li><li>Visite sur site ou contrôle sur pièces (dématérialisé depuis 2022).</li><li>Communication avec l'inspecteur pendant le contrôle : réponses écrites.</li><li>Réception de la <strong>lettre d'observations</strong> détaillant les points de non-conformité.</li><li>Période contradictoire de <strong>30 jours</strong> pour répondre.</li><li>Notification finale de redressement ou classement sans suite.</li><li>En cas de désaccord : saisine de la <strong>CRA</strong> (Commission de Recours Amiable) puis TASS.</li></ol><p><strong>Points sensibles récurrents :</strong></p><ul><li>Frais professionnels (justificatifs, plafonds, avantages en nature véhicule).</li><li>Réduction générale de cotisations (formule exacte, prise en compte HS).</li><li>Heures sup exonérées (respect des accords collectifs).</li><li>PPV (respect des conditions cumulatives).</li><li>Contribution 100 % maladie (salaires > 2,5 SMIC).</li><li>Requalification des indemnités de rupture en salaire.</li></ul>${info("Bonnes pratiques préventives", "<ul><li>Audit annuel interne par un expert-comptable ou consultant paie.</li><li>Archivage numérique organisé (6 ans URSSAF, 10 ans compta, 50 ans DSN).</li><li>Procédures écrites : circuit EVP, contrôles croisés DSN/paie/compta.</li><li>Documentation des choix (accord d'entreprise, note interne).</li><li>Utilisation de la <strong>rescrit social</strong> URSSAF pour sécuriser une pratique.</li></ul>")}` },
        { title: "Tableaux de bord et indicateurs paie", content: `${photo(IMG.ordinateur, "Reporting paie et KPI")}<p>Le gestionnaire de paie pilote et contrôle son activité via quelques <strong>KPI clés</strong> :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:13px"><tr style="background:#f0f0f0"><th>Indicateur</th><th>Formule</th><th>Interprétation</th></tr><tr><td>Masse salariale brute</td><td>Σ brut mensuel × 12</td><td>Base de pilotage RH</td></tr><tr><td>Masse salariale chargée</td><td>Brut + charges patronales</td><td>Coût réel employeur</td></tr><tr><td>Coût moyen salarié</td><td>MS chargée / effectif ETP</td><td>Benchmark sectoriel</td></tr><tr><td>Taux d'absentéisme</td><td>Jours abs / jours théoriques × 100</td><td>Alerte si > 5 %</td></tr><tr><td>Turnover</td><td>((entrées + sorties)/2) / effectif × 100</td><td>Alerte si > 15 %</td></tr><tr><td>Taux de charges</td><td>Charges patronales / brut × 100</td><td>~42 % standard, ~15 % au SMIC</td></tr><tr><td>Provisions CP</td><td>Solde CP × taux horaire × 1,10</td><td>Comptabilisation mensuelle</td></tr><tr><td>Provisions 13ᵉ mois</td><td>Brut / 12 × mois écoulés</td><td>Provisionnable ligne 4282</td></tr></table><p><strong>Tableau de bord mensuel type</strong> à produire pour la direction : effectif, entrées/sorties, MS brute et chargée, absentéisme, arrêts maladie, HS payées, retards DSN, contrôles en cours.</p>` },
        { title: "Veille sociale et sources professionnelles", content: `<p>Le droit social évolue en permanence : lois de financement de la sécurité sociale (LFSS), lois de finances, décrets, jurisprudence, conventions collectives, doctrine administrative.</p><p><strong>Sources fiables et gratuites :</strong></p><ul><li><strong>Legifrance</strong> — texte officiel des lois, décrets, arrêtés.</li><li><strong>BOSS.gouv.fr</strong> (Bulletin Officiel de la Sécurité Sociale) — opposabilité à l'URSSAF depuis 2021, référence n° 1.</li><li><strong>URSSAF Caisse Nationale</strong> — barèmes, simulateurs, actualités.</li><li><strong>Net-entreprises.fr</strong> — norme DSN, cahiers techniques.</li><li><strong>Service-public.fr Pro</strong> — vulgarisation officielle.</li><li><strong>Ameli.fr</strong> — IJSS, arrêts, maternité.</li></ul><p><strong>Sources payantes de référence :</strong></p><ul><li><strong>Editions Législatives</strong> (Liaisons sociales, Dictionnaire permanent social).</li><li><strong>Éditions Francis Lefebvre</strong> (Mémento Paie).</li><li><strong>Editions Tissot</strong>, <strong>Wolters Kluwer</strong> (Lamy Paie).</li><li><strong>RF Paye</strong>, <strong>Cegos</strong>.</li></ul><p><strong>Communautés et associations :</strong> ANDRH, DFCG, groupes LinkedIn "Gestionnaires de paie", webinaires URSSAF mensuels.</p>${info("Rythme de veille recommandé", "<ul><li><strong>Hebdomadaire</strong> : lecture Liaisons sociales quotidien / newsletters URSSAF.</li><li><strong>Mensuel</strong> : point sur les CRM DSN, jurisprudence Cass. soc.</li><li><strong>Trimestriel</strong> : convention collective + accords d'entreprise en vigueur.</li><li><strong>Annuel</strong> : audit paramétrage logiciel, mise à jour barèmes.</li></ul>")}` },
        { title: "RGPD, confidentialité et cybersécurité en paie", content: `<p>La paie manipule des données <strong>sensibles</strong> au sens du RGPD :</p><ul><li>Données d'état civil, coordonnées, RIB.</li><li>Numéro de sécurité sociale (NIR) — catégorie particulière.</li><li>Données de santé (arrêts, IJSS, invalidité).</li><li>Rémunérations, primes, saisies sur salaire.</li><li>Situation familiale, enfants, RQTH.</li></ul><p><strong>Obligations principales :</strong></p><ul><li><strong>Registre des traitements</strong> tenu à jour (art. 30 RGPD).</li><li><strong>Durées de conservation</strong> maîtrisées : 5 ans (bulletins papier depuis dématérialisation), 6 ans (URSSAF), 50 ans (DSN pour carrière), archivage anonymisé au-delà.</li><li><strong>Droits des salariés</strong> : accès, rectification, portabilité (transfert vers nouvel employeur).</li><li><strong>Accès restreint</strong> par profil dans le logiciel de paie (principe du besoin d'en connaître).</li><li><strong>Sécurisation</strong> : chiffrement des bases, MFA sur SaaS, sauvegardes, plan de reprise.</li><li><strong>Notification CNIL sous 72 h</strong> en cas de fuite de données.</li></ul>${warn("Bulletin dématérialisé", "Depuis 2017, l'employeur peut remettre le bulletin sous format électronique <strong>sauf opposition du salarié</strong>. Obligation : coffre-fort numérique sécurisé (Digiposte, PeopleDoc), conservation garantie 50 ans, information préalable du salarié.")}` },
        { title: "Posture professionnelle et éthique du gestionnaire de paie", content: `<p>Le gestionnaire de paie n'est pas un simple exécutant technique. Sa posture est essentielle :</p><ul><li><strong>Rigueur absolue</strong> : une erreur coûte cher (rappel URSSAF, contentieux salariés, perte de confiance).</li><li><strong>Confidentialité</strong> : ne jamais divulguer un salaire, une prime, un arrêt maladie — même entre collègues du service.</li><li><strong>Pédagogie</strong> : savoir expliquer un bulletin à un salarié qui ne comprend pas (rôle d'interface).</li><li><strong>Neutralité</strong> : appliquer la règle avec équité, quel que soit le niveau hiérarchique du salarié.</li><li><strong>Alerte</strong> : signaler à l'employeur toute non-conformité (heures sup non payées, minima non respectés, discrimination salariale) — devoir d'alerte protégé par la loi Sapin II.</li><li><strong>Curiosité</strong> : la formation continue est indispensable (10 h/an minimum de veille).</li><li><strong>Diplomatie</strong> : gérer les tensions (retards de paie, erreurs, saisies) sans dramatiser.</li></ul>${info("Évolution professionnelle", "Le gestionnaire de paie confirmé (5 ans) évolue vers : responsable paie (encadrement d'équipe), consultant paie (cabinet d'expertise-comptable), chef de projet paie (déploiement logiciel), contrôleur de gestion sociale, DRH PME. Rémunération 2026 : 28-38 k€ débutant, 40-55 k€ confirmé, 55-75 k€ responsable paie.")}` },
        { title: "Paramétrage d'un logiciel de paie (Silae, Sage, Cegid, PayFit)", content: `<p>Le choix et le paramétrage du <strong>logiciel de paie</strong> conditionnent la fiabilité de toute la production. Comparatif 2026 :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:12px"><tr style="background:#f0f0f0"><th>Logiciel</th><th>Cible</th><th>Points forts</th><th>Limites</th></tr><tr><td><strong>Silae</strong></td><td>Cabinets EC, PME</td><td>Paramétrage fin, DSN robuste, coffre-fort intégré</td><td>Prise en main longue (~40 h)</td></tr><tr><td><strong>Sage Paie</strong></td><td>PME / ETI</td><td>Multi-établissements, ERP-friendly</td><td>Coût licence élevé</td></tr><tr><td><strong>Cegid Talentsoft</strong></td><td>ETI / grands comptes</td><td>SIRH complet, workflow validation</td><td>Complexité, TCO élevé</td></tr><tr><td><strong>PayFit</strong></td><td>TPE / PME < 200 sal.</td><td>UX moderne, self-service salarié, veille auto</td><td>Personnalisation limitée</td></tr><tr><td><strong>ADP Décidium</strong></td><td>ETI internationales</td><td>Multi-pays, reporting avancé</td><td>Onboarding lourd</td></tr><tr><td><strong>EBP Paie</strong></td><td>TPE indépendants</td><td>Simplicité, prix</td><td>Fonctionnalités limitées</td></tr></table><p><strong>Check-list de paramétrage initial :</strong></p><ol><li>Fiche société : SIRET, APE, IDCC, effectif MSA/URSSAF, taux AT/MP, code caisse retraite, N° prévoyance.</li><li>Paramétrage des <strong>rubriques de paie</strong> (bases, taux, plafond, imposable IR/CSG, DSN).</li><li>Import <strong>plan comptable</strong> et OD de paie (comptes 641X, 645X, 43X, 421X).</li><li>Grilles de <strong>classifications</strong> et minima conventionnels.</li><li>Barèmes : SMIC, PMSS, avantages en nature, indemnités.</li><li>Salariés : contrat, ancienneté, taux PAS, RIB, ayants droit mutuelle.</li><li>Cycle de paie : dates de clôture, workflow validation, bank file (SEPA).</li></ol>${warn("Reprise d'historique", "Lors d'un changement de logiciel en cours d'année, reprendre impérativement : cumuls bruts, nets, CSG, réduction générale, CP acquis/pris, ancienneté DIF/CPF, arrêts en cours. Sans quoi : PMSS mal calculé, plafonds annuels faussés, DSN de reprise rejetée.")}` },
        { title: "Contrôle de gestion sociale : masse salariale, ratios, GVT", content: `<p>Le <strong>contrôle de gestion sociale (CGS)</strong> est le prolongement naturel du métier de paie. Il consiste à piloter la masse salariale et à projeter son évolution.</p><p><strong>Décomposition du GVT</strong> (Glissement Vieillissement Technicité) — moteur d'évolution mécanique de la MS :</p><ul><li><strong>G — Glissement</strong> : augmentations individuelles au mérite (~1-2 %/an).</li><li><strong>V — Vieillissement</strong> : progression automatique à l'ancienneté (primes, échelons) (~0,5-1 %/an).</li><li><strong>T — Technicité</strong> : promotions, changements de classification (~0,3-0,8 %/an).</li></ul><p><strong>Effet report / effet niveau / effet masse :</strong></p><ul><li><strong>Effet niveau</strong> : variation entre 12ᵉ mois N-1 et 12ᵉ mois N (photo instantanée).</li><li><strong>Effet masse</strong> : variation de la MS annuelle N vs N-1 (impact réel budget).</li><li><strong>Effet report</strong> : impact sur N+1 d'une augmentation intervenue en cours de N.</li></ul>${exo("Effet report", "Une augmentation générale de 2 % au 1er juillet N. Calculez effet masse N et effet report sur N+1.", "<p><strong>Effet masse N :</strong> 2 % × 6/12 = <strong>+1 %</strong> sur la MS N.</p><p><strong>Effet report N+1 :</strong> 2 % × 6/12 = <strong>+1 %</strong> sur la MS N+1 (avant tout nouvel arbitrage).</p><p>Un DAF doit systématiquement budgéter l'effet report avant de valider les négociations annuelles obligatoires (NAO).</p>")}` },
        { title: "Saisies sur salaire, avis à tiers détenteur, pension alimentaire", content: `<p>Le gestionnaire peut être destinataire de <strong>saisies</strong> qu'il doit exécuter sous peine de sanction :</p><ul><li><strong>Saisie-attribution (huissier)</strong> — dettes civiles.</li><li><strong>ATD / SATD</strong> (Saisie Administrative à Tiers Détenteur) — dettes fiscales, ex-avis à tiers détenteur.</li><li><strong>Pension alimentaire</strong> — jugement JAF, priorité absolue.</li><li><strong>Cession sur salaire</strong> — accord volontaire du salarié (crédit à la consommation).</li></ul><p><strong>Barème saisie 2026</strong> (art. R. 3252-2 CT, tranches annuelles pour 1 personne à charge, à majorer de ~1 720 € par personne supplémentaire) :</p><table border="1" cellpadding="6" style="width:100%;border-collapse:collapse;font-size:12px"><tr style="background:#f0f0f0"><th>Tranche rému annuelle</th><th>Quotité saisissable</th></tr><tr><td>≤ 4 370 €</td><td>1/20</td></tr><tr><td>4 370 → 8 520 €</td><td>1/10</td></tr><tr><td>8 520 → 12 690 €</td><td>1/5</td></tr><tr><td>12 690 → 16 820 €</td><td>1/4</td></tr><tr><td>16 820 → 21 000 €</td><td>1/3</td></tr><tr><td>21 000 → 25 220 €</td><td>2/3</td></tr><tr><td>> 25 220 €</td><td>Totalité</td></tr></table><p>La <strong>fraction absolument insaisissable</strong> = montant du RSA pour une personne seule (~635 €/mois en 2026). La pension alimentaire prime sur toutes les autres saisies et se prélève <em>même sur le RSA</em>.</p>${warn("Responsabilité employeur", "Un employeur qui ne verse pas la saisie devient <strong>débiteur personnel</strong> de la dette (art. R. 3252-27 CT). Verser au bon organisme (Trésor public, greffe, créancier) et conserver la preuve de virement.")}` },
      ],
    },
  ];
}
